/**
 * THE THREE FILES OF A SHADOW COMMIT, GENERATED BY THE SERVER, AND NOTHING ELSE.
 *
 * One exec step that runs on GitHub's free computers is one push of a
 * throwaway `tailzu-run/` branch (shadow.ts, githubActions.ts) whose commit
 * adds exactly:
 *
 *   .github/workflows/tailzu-run.yml   renderWorkflow(): written here, from one
 *                                      function, and pinned by a golden test
 *   .tailzu/step.json                  stepJson(): what to run and where to report (and,
 *                                      for a trial run of the agent's edits, the files
 *                                      to lay over the checkout first)
 *   .tailzu/run.mjs                    runScript.ts, byte for byte
 *
 * THE WORKFLOW. It runs on a push to `tailzu-run/**` only; asks GitHub for
 * read access to the contents and an identity token (`id-token: write`, which
 * is what lets the script prove to Tailzu who it is) and nothing more; has one
 * job on `ubuntu-latest` with a timeout from the step; checks the branch out
 * with its whole history (the script diffs against the work branch's
 * checkpoint, which is the commit's parent) and without keeping the token in
 * git's config; restores the package managers' caches; and runs the script.
 * The actions are pinned by major version. A second push of the same branch
 * would cancel the first run (the concurrency group is the ref, with a
 * `tailzu-run-` in front so it can't be the same group as one of the person's
 * own workflows that uses the bare ref, which would cancel the other).
 *
 * THE TIMEOUT. GitHub's own `timeout-minutes` is the step's time rounded up to
 * the minute plus one, so the script has a minute to collect its changes and
 * report after its commands have had all the time they were given. The ticker
 * (router.ts) gives up on the run a minute after that.
 */
import { SHADOW_SCRIPT, SHADOW_STEP, SHADOW_WORKFLOW } from "../shadow.js";
import { RUN_MJS } from "./runScript.js";
import type { OverlayFile } from "./types.js";

/** The lockfiles the cache is keyed on. */
export const LOCKFILES: readonly string[] = [
  "**/package-lock.json", "**/yarn.lock", "**/pnpm-lock.yaml", "**/requirements*.txt", "**/poetry.lock", "**/Pipfile.lock",
];

/** The folders the package managers keep what they download in. */
export const CACHE_PATHS: readonly string[] = ["~/.npm", "~/.cache/pip", "~/.cache/yarn", "~/.local/share/pnpm"];

/** GitHub's job timeout for a step of `timeoutSec` seconds: the step's minutes rounded up, and one more to collect and report. */
export function timeoutMinutes(timeoutSec: number): number {
  const sec = Number.isFinite(timeoutSec) ? Math.max(1, timeoutSec) : 600;
  return Math.ceil(sec / 60) + 1;
}

/** `.github/workflows/tailzu-run.yml`. */
export function renderWorkflow(minutes: number): string {
  const lock = LOCKFILES.map((f) => `'${f}'`).join(", ");
  return [
    "# Written by Tailzu for one step of a coding job. Do not edit: it is replaced for every step.",
    "# It runs only for the throwaway tailzu-run/ branch it was written on, and the branch is deleted afterwards.",
    "name: Tailzu run",
    "on:",
    "  push:",
    "    branches: ['tailzu-run/**']",
    "permissions:",
    "  contents: read",
    "  id-token: write",
    "concurrency:",
    "  group: tailzu-run-${{ github.ref }}",
    "  cancel-in-progress: true",
    "jobs:",
    "  run:",
    "    runs-on: ubuntu-latest",
    `    timeout-minutes: ${Math.max(1, Math.floor(minutes))}`,
    "    steps:",
    "      - uses: actions/checkout@v4",
    "        with:",
    "          fetch-depth: 0",
    "          persist-credentials: false",
    "      - uses: actions/cache@v4",
    "        with:",
    "          path: |",
    ...CACHE_PATHS.map((p) => `            ${p}`),
    `          key: tailzu-\${{ runner.os }}-\${{ hashFiles(${lock}) }}`,
    "          restore-keys: |",
    "            tailzu-${{ runner.os }}-",
    "      - run: node .tailzu/run.mjs",
    "",
  ].join("\n");
}

/** What `.tailzu/step.json` holds. */
export interface StepSpec {
  jobId: string;
  stepIdx: number;
  /** The lease epoch the step was dispatched under. */
  epoch: number;
  commands: string[];
  timeoutSec: number;
  /** The work branch's checkpoint: the commit the shadow commit sits on, and what the changes are measured against. */
  baseSha: string;
  /** Where the script reports (POST /v1/code/runner/gh-result). */
  resultUrl: string;
  /** The audience of the identity token the script asks GitHub for. */
  audience: string;
  /** Files the script writes over its checkout before the commands run (the agent's staged edits). Left out of the file when there are none. */
  overlay?: OverlayFile[];
  /** The step's changes are not wanted: the script does not collect or send them. Left out of the file when false. */
  discard?: boolean;
}

export function stepJson(spec: StepSpec): string {
  return `${JSON.stringify({
    jobId: spec.jobId, stepIdx: spec.stepIdx, epoch: spec.epoch, commands: spec.commands, timeoutSec: spec.timeoutSec,
    baseSha: spec.baseSha, resultUrl: spec.resultUrl, audience: spec.audience,
    ...(spec.overlay?.length ? { overlay: spec.overlay } : {}), ...(spec.discard ? { discard: true } : {}),
  }, null, 2)}\n`;
}

/** The three files of a shadow commit, in the order they are written. */
export function shadowFiles(spec: StepSpec): Array<{ path: string; content: string }> {
  return [
    { path: SHADOW_WORKFLOW, content: renderWorkflow(timeoutMinutes(spec.timeoutSec)) },
    { path: SHADOW_STEP, content: stepJson(spec) },
    { path: SHADOW_SCRIPT, content: RUN_MJS },
  ];
}
